        threading.Thread(target=_blind_sound, daemon=True, name="blind-sound").start()


def _ssh_stderr(r) -> str:
    return ((getattr(r, "stderr", b"") or b"").decode("utf-8", "replace").strip().splitlines() or ["—"])[-1][:200]


